#!/usr/bin/env node
/* Builds android/app/assets/www/kestrel-skills.js from skill repositories that
 * were cloned into study/ (see study/README.md). The generated file is what
 * ships: the WebView cannot read the study folders, and a phone app must work
 * offline.
 *
 *   node android/tools/collect-skills.js
 *
 * Adding a repository: clone it under study/, then add it to SOURCES below.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..', '..');
const SOURCES = [
  { id: 'ponytail', repo: 'DietrichGebert/ponytail', dir: 'study/ponytail/skills' },
  { id: 'agent-skills', repo: 'addyosmani/agent-skills', dir: 'study/agent-skills/skills' },
];

/** Splits YAML frontmatter into flat key/value pairs and returns the rest. */
function splitFrontmatter(raw) {
  const text = raw.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
  const match = text.match(/^---\n([\s\S]*?)\n---\n?/);
  if (!match) return { meta: {}, body: text.trim() };
  const meta = {};
  let key = null;
  for (const line of match[1].split('\n')) {
    const pair = line.match(/^([A-Za-z0-9_-]+):\s*(.*)$/);
    if (pair) {
      key = pair[1];
      meta[key] = pair[2].replace(/^[>|]\s*/, '');
      continue;
    }
    if (key && /^\s+\S/.test(line)) meta[key] = (meta[key] ? meta[key] + ' ' : '') + line.trim();
  }
  for (const k of Object.keys(meta)) meta[k] = meta[k].replace(/\s+/g, ' ').trim();
  return { meta, body: text.slice(match[0].length).trim() };
}

const skills = [];
for (const source of SOURCES) {
  const base = path.join(root, source.dir);
  if (!fs.existsSync(base)) {
    console.error('skip ' + source.id + ': ' + source.dir + ' is not cloned');
    continue;
  }
  for (const entry of fs.readdirSync(base).sort()) {
    const dir = path.join(base, entry);
    if (!fs.statSync(dir).isDirectory()) continue;
    const file = path.join(dir, 'SKILL.md');
    if (!fs.existsSync(file)) continue;
    const { meta, body } = splitFrontmatter(fs.readFileSync(file, 'utf8'));
    const name = (meta.name || entry).trim();
    skills.push({
      name: name,
      source: source.id,
      repo: source.repo,
      description: (meta.description || '').slice(0, 400),
      text: body,
    });
  }
}

skills.sort(function (a, b) {
  if (a.source !== b.source) return a.source < b.source ? -1 : 1;
  return a.name < b.name ? -1 : 1;
});

const out = path.join(root, 'android', 'app', 'assets', 'www', 'kestrel-skills.js');
const banner =
  '/* Generated by android/tools/collect-skills.js — do not edit by hand.\n' +
  ' * ' + skills.length + ' skills from ' + SOURCES.length + ' repositories, bundled so the phone works offline.\n' +
  ' * Content belongs to its upstream projects; see android/README.md for licences.\n' +
  ' */\n';
fs.writeFileSync(
  out,
  banner +
    '\n(function (root) {\n  root.KESTREL_SKILLS = ' +
    JSON.stringify(skills, null, 0) +
    ';\n})(typeof globalThis !== "undefined" ? globalThis : this);\n'
);

const bytes = fs.statSync(out).size;
console.log(skills.length + ' skills → ' + path.relative(root, out) + ' (' + Math.round(bytes / 1024) + ' KB)');
for (const s of skills) console.log('  ' + s.source.padEnd(12) + s.name.padEnd(34) + Math.round(s.text.length / 1024) + ' KB');
